17	template <typename DstTileData, typename Src0TileData, typename Src1TileData, typename TmpTileData>
18	PTO_INTERNAL void CheckValid()
19	{
20	    static_assert(
21	        (sizeof(typename DstTileData::DType) == 2) || (sizeof(typename DstTileData::DType) == 4),
22	        "Fix: TGATHER expect b16/b32");
23	    static_assert((sizeof(typename Src1TileData::DType) == 4), "Fix: TGATHER expect b32");
24	    static_assert(
25	        (std::is_same<typename DstTileData::DType, typename Src0TileData::DType>::value),
26	        "Fix: TGATHER expect same datatype for src and dst");
27	    static_assert(
28	        (std::is_same<typename TmpTileData::DType, typename Src1TileData::DType>::value),
29	        "Fix: TGATHER expect same datatype for tmp buffer and indice");
30	}
31	
32	template <typename TileDataD, typename TileDataS0, typename TileDataS1, typename TileDataTmp>
33	__tf__ AICORE void TGather(
34	    typename TileDataD::TileDType __out__ dst, typename TileDataS0::TileDType __in__ src0,
35	    typename TileDataS1::TileDType __in__ src1, typename TileDataTmp::TileDType __in__ tmp, unsigned validCol,
36	    unsigned validRow)
37	{
38	    __ubuf__ typename TileDataS0::DType* src0Ptr = (__ubuf__ typename TileDataS0::DType*)__cce_get_tile_ptr(src0);
39	    __ubuf__ typename TileDataS1::DType* src1Ptr = (__ubuf__ typename TileDataS1::DType*)__cce_get_tile_ptr(src1);
40	    __ubuf__ typename TileDataD::DType* dstPtr = (__ubuf__ typename TileDataD::DType*)__cce_get_tile_ptr(dst);
41	    __ubuf__ typename TileDataTmp::DType* tmpPtr = (__ubuf__ typename TileDataTmp::DType*)__cce_get_tile_ptr(tmp);
42	
43	    unsigned TShape0 = TileDataD::Rows;
44	    unsigned TShape1 = TileDataD::Cols;
45	    unsigned idx_stride = TileDataS1::Cols;
46	    constexpr unsigned blockSizeElem = BLOCK_BYTE_SIZE / sizeof(typename TileDataD::DType);
47	    constexpr unsigned elementsPerRepeat = REPEAT_BYTE / sizeof(typename TileDataD::DType);
48	    constexpr unsigned stride = TileDataD::RowStride;
49	    unsigned numRepeatPerLine = validCol / elementsPerRepeat;
50	    unsigned numRemainPerLine = validCol % elementsPerRepeat;
51	    unsigned numLoop = numRepeatPerLine / REPEAT_MAX;
52	    unsigned remainAfterLoop = numRepeatPerLine % REPEAT_MAX;
53	
54	    if constexpr (
55	        std::is_same_v<typename TileDataS0::DType, float> || std::is_same_v<typename TileDataS0::DType, int32_t> ||
56	        std::is_same_v<typename TileDataS0::DType, uint32_t>) {
57	        // 64 element per VL
58	        // counter mode
59	        set_mask_count();
60	        for (int i = 0; i < validRow; i++) {
61	            set_vector_mask(0, validCol);
62	            vmuls(
63	                (__ubuf__ int32_t*)(dstPtr + i * TShape1), (__ubuf__ int32_t*)(src1Ptr + i * idx_stride),
64	                sizeof(typename TileDataD::DType), 1, 1, 1, 8, 8);
65	            pipe_barrier(PIPE_V);
66	            vgather(
67	                (__ubuf__ uint32_t*)(dstPtr + i * TShape1), (__ubuf__ uint32_t*)(dstPtr + i * TShape1),
68	                (uintptr_t)src0Ptr, 8, 1);
69	        }
70	
71	        set_mask_norm();
72	        set_vector_mask(-1, -1);
73	    } else {
74	        // 128 element per VL
75	        // counter mode
76	        set_mask_count();
77	        for (int i = 0; i < validRow; i++) {
78	            set_vector_mask(0, validCol);
79	            vmuls(
80	                (__ubuf__ int32_t*)(tmpPtr + i * TShape1), (__ubuf__ int32_t*)(src1Ptr + i * idx_stride),
81	                sizeof(typename TileDataD::DType), 1, 1, 1, 8, 8);
82	            pipe_barrier(PIPE_V);
83	            vgather(
84	                (__ubuf__ uint16_t*)(dstPtr + i * TShape1), (__ubuf__ uint32_t*)(tmpPtr + i * TShape1),
85	                (uintptr_t)src0Ptr, 8, 1);
86	        }
87	        set_mask_norm();
88	        set_vector_mask(-1, -1);
89	    }
90	}
91	
92	template <typename TileDataD, typename TileDataS0, typename TileDataS1, typename TileDataTmp>
93	PTO_INTERNAL void TGATHER_IMPL(TileDataD& dst, TileDataS0& src0, TileDataS1& src1, TileDataTmp& tmp)
94	{
95	    CheckValid<TileDataD, TileDataS0, TileDataS1, TileDataTmp>();
96	    PTO_ASSERT(src1.GetValidCol() == tmp.GetValidCol(), "Fix: TGATHER expect same cols for indice and tmp buffer.");
97	    PTO_ASSERT(src1.GetValidRow() == tmp.GetValidRow(), "Fix: TGATHER expect same rows for indice and tmp buffer.");
98	
99	    unsigned validCol = dst.GetValidCol();
100	    unsigned validRow = dst.GetValidRow();
101	
102	    TGather<TileDataD, TileDataS0, TileDataS1, TileDataTmp>(
103	        dst.data(), src0.data(), src1.data(), tmp.data(), validCol, validRow);
104	}
105	
106	template <typename DstTileData, typename SrcTileData, MaskPattern maskPattern, auto gatherType = GatherAxis::GATHER_ROW>
107	__tf__ AICORE void TGather(
108	    typename DstTileData::TileDType __out__ dst, typename SrcTileData::TileDType __in__ src, unsigned validRow,
109	    unsigned validCol)
110	{
111	    using T = typename SrcTileData::DType;
112	    using U = std::conditional_t<sizeof(T) == sizeof(uint32_t), uint32_t, uint16_t>;
113	
114	    constexpr unsigned srcRepeatStride = SrcTileData::Cols * sizeof(T) / BLOCK_BYTE_SIZE;
115	    constexpr unsigned dstStride = DstTileData::RowStride;
116	    constexpr unsigned srcStride = SrcTileData::RowStride;
117	
118	    __ubuf__ typename DstTileData::DType* dstPtr = (__ubuf__ typename DstTileData::DType*)__cce_get_tile_ptr(dst);
119	    __ubuf__ typename SrcTileData::DType* srcPtr = (__ubuf__ typename SrcTileData::DType*)__cce_get_tile_ptr(src);
120	
121	    set_mask_count();
122	    set_vector_mask(0, validCol);
123	    if constexpr (gatherType == GatherAxis::GATHER_COL) {
124	        uint16_t stride = 0;
125	        for (int i = 0; i < validRow; i++) {
126	            stride = GetStrideByMask<maskPattern, srcStride>(i);
127	            vcopy((__ubuf__ U*)(dstPtr + i * dstStride), (__ubuf__ U*)(srcPtr + stride), 1, 1, 1, 8, 8);
128	        }
129	    } else {
130	        vreducev2(
131	            reinterpret_cast<__ubuf__ U*>(dstPtr), reinterpret_cast<__ubuf__ U*>(srcPtr),
132	            reinterpret_cast<__ubuf__ U*>(srcPtr), validRow, 1, maskPattern, srcRepeatStride, 0);
133	    }
134	    set_mask_norm();
135	    set_vector_mask(-1, -1);
136	}
137	
138	template <typename DstTileData, typename SrcTileData, MaskPattern maskPattern, auto gatherType = GatherAxis::GATHER_ROW>
139	PTO_INTERNAL void TGATHER_IMPL(DstTileData& dst, SrcTileData& src)
140	{
141	    using T = typename SrcTileData::DType;
142	    unsigned validRow = src.GetValidRow();
143	    unsigned validCol = src.GetValidCol();
144	    static_assert(sizeof(T) == 2 || sizeof(T) == 4, "Fix: TGATHER src element type must be 16 or 32-bit wide");
145	    static_assert(
146	        (DstTileData::Loc == TileType::Vec) && (SrcTileData::Loc == TileType::Vec), "Fix: TGATHER expect vec TileType");
147	    static_assert((DstTileData::isRowMajor && SrcTileData::isRowMajor), "Fix: TGATHER expect row major");
148	    static_assert(
149	        (sizeof(typename DstTileData::DType) == sizeof(T)), "Fix: TGATHER expect same type size for dst and src");
150	    if constexpr (gatherType == GatherAxis::GATHER_ROW) {
151	        PTO_ASSERT(dst.GetValidCol() == DstTileData::Cols, "Fix: TGATHER expect continuous memory for dst.");
152	    } else {
153	        PTO_ASSERT(
154	            validRow == dst.GetValidRow() * GetTimesByMask<maskPattern>,
155	            "Fix: TGATHER validRow of dst must be 2 or 4 times that of src.");
156	    }
157	    TGather<DstTileData, SrcTileData, maskPattern, gatherType>(dst.data(), src.data(), validRow, validCol);
158	}
