160	template <typename TileDataD, typename TileDataS, typename TileDataS1>
161	AICORE void TGather_cmp_FillIndexAndConvertK(
162	    __ubuf__ typename TileDataD::DType* indexTmpPtr, uint32_t offset, __ubuf__ typename TileDataS::DType* cvtTmpPtr,
163	    __ubuf__ typename TileDataS1::DType* kPtr, unsigned srcValidRow)
164	{
165	    using TIN = typename TileDataS::DType;
166	
167	    for (int i = 0; i < TileDataS::Rows * TileDataS::Cols; i++) {
168	        *(indexTmpPtr + i) = offset + i;
169	    }
170	    PtoSetWaitFlag<PIPE_S, PIPE_V>();
171	
172	    unsigned numRepeat = CeilDivision(srcValidRow, (REPEAT_BYTE / sizeof(typename TileDataS1::DType)));
173	    if constexpr (std::is_same_v<TIN, float>) {
174	        vconv_s322f32(cvtTmpPtr, reinterpret_cast<__ubuf__ int32_t*>(kPtr), numRepeat, 1, 1, 8, 8);
175	    } else if constexpr (std::is_same_v<TIN, int32_t>) {
176	        for (int i = 0; i < TileDataS::Rows; i++) {
177	            *(cvtTmpPtr + i) = *(kPtr + i);
178	        }
179	    } else if constexpr (std::is_same_v<TIN, half>) {
180	        vconv_s162f16(cvtTmpPtr, reinterpret_cast<__ubuf__ int16_t*>(kPtr), numRepeat, 1, 1, 8, 8);
181	    }
182	}
183	
184	template <typename TileDataS, typename TileDataTmp, CmpMode cmpMode>
185	AICORE void TGather_cmp_RunTcmps(
186	    __ubuf__ typename TileDataS::DType* cvtTmpPtr, __ubuf__ typename TileDataS::DType* src0Ptr,
187	    __ubuf__ uint8_t* cmpsTmpPtr, unsigned srcValidCol, unsigned srcValidRow)
188	{
189	    using TIN = typename TileDataS::DType;
190	
191	    unsigned numRepeatPerLine = CeilDivision(srcValidCol, (REPEAT_BYTE / sizeof(TIN)));
192	    size_t nLoop = numRepeatPerLine / TCMPS_REPEAT_MAX;
193	    int remainPerLine = numRepeatPerLine % TCMPS_REPEAT_MAX;
194	    constexpr int srcAlignCols = TileDataS::Cols;
195	    constexpr int dstAlignCols = TileDataTmp::Cols;
196	    constexpr int srcOffset = TCMPS_REPEAT_MAX * REPEAT_BYTE / sizeof(TIN);
197	    constexpr int dstOffset = TCMPS_REPEAT_MAX * REPEAT_BYTE / sizeof(TIN) / NUM_BITS_IN_BYTE;
198	    set_mask_norm();
199	    set_vector_mask(-1, -1);
200	    for (size_t i = 0; i < srcValidRow; i++) {
201	        PtoSetWaitFlag<PIPE_V, PIPE_S>();
202	        TIN k_scalar = *(cvtTmpPtr + i);
203	        PtoSetWaitFlag<PIPE_S, PIPE_V>();
204	        for (size_t j = 0; j < nLoop; j++) {
205	            if constexpr (cmpMode == CmpMode::GT) {
206	                vcmpvs_gt(
207	                    cmpsTmpPtr + i * dstAlignCols + j * dstOffset, src0Ptr + i * srcAlignCols + j * srcOffset, k_scalar,
208	                    TCMPS_REPEAT_MAX, 1, 1, 8, 8);
209	            } else {
210	                vcmpvs_eq(
211	                    cmpsTmpPtr + i * dstAlignCols + j * dstOffset, src0Ptr + i * srcAlignCols + j * srcOffset, k_scalar,
212	                    TCMPS_REPEAT_MAX, 1, 1, 8, 8);
213	            }
214	        }
215	    }
216	    if (remainPerLine) {
217	        for (size_t i = 0; i < srcValidRow; i++) {
218	            PtoSetWaitFlag<PIPE_V, PIPE_S>();
219	            TIN k_scalar = *(cvtTmpPtr + i);
220	            PtoSetWaitFlag<PIPE_S, PIPE_V>();
221	            if constexpr (cmpMode == CmpMode::GT) {
222	                vcmpvs_gt(
223	                    cmpsTmpPtr + i * dstAlignCols + nLoop * dstOffset, src0Ptr + i * srcAlignCols + nLoop * srcOffset,
224	                    k_scalar, remainPerLine, 1, 1, 8, 8);
225	            } else {
226	                vcmpvs_eq(
227	                    cmpsTmpPtr + i * dstAlignCols + nLoop * dstOffset, src0Ptr + i * srcAlignCols + nLoop * srcOffset,
228	                    k_scalar, remainPerLine, 1, 1, 8, 8);
229	            }
230	        }
231	    }
232	}
233	
234	template <typename TileDataD, typename TileDataS, typename TileDataS1, typename TileDataTmp, CmpMode cmpMode>
235	AICORE void TGather_cmp_InitIndicesKAndTcmps(
236	    __ubuf__ typename TileDataD::DType* indexTmpPtr, uint32_t offset, __ubuf__ typename TileDataS::DType* cvtTmpPtr,
237	    __ubuf__ typename TileDataS1::DType* kPtr, __ubuf__ typename TileDataS::DType* src0Ptr,
238	    __ubuf__ uint8_t* cmpsTmpPtr, unsigned srcValidCol, unsigned srcValidRow)
239	{
240	    TGather_cmp_FillIndexAndConvertK<TileDataD, TileDataS, TileDataS1>(
241	        indexTmpPtr, offset, cvtTmpPtr, kPtr, srcValidRow);
242	    TGather_cmp_RunTcmps<TileDataS, TileDataTmp, cmpMode>(cvtTmpPtr, src0Ptr, cmpsTmpPtr, srcValidCol, srcValidRow);
243	}
244	
245	template <typename TileDataD, typename TileDataS, typename TileDataC, typename TileDataTmp>
246	AICORE void TGather_cmp_ReduceGatherAndCounts(
247	    __ubuf__ typename TileDataD::DType* dstPtr, __ubuf__ typename TileDataD::DType* indexTmpPtr,
248	    __ubuf__ uint8_t* cmpsTmpPtr, __ubuf__ typename TileDataC::DType* cdstPtr, unsigned srcValidRow,
249	    unsigned srcValidCol)
250	{
251	    using T = typename TileDataD::DType;
252	
253	    pipe_barrier(PIPE_V);
254	
255	    set_mask_count();
256	    set_vector_mask(0, srcValidCol);
257	    for (int i = 0; i < srcValidRow; i++) {
258	        vreducev2(
259	            reinterpret_cast<__ubuf__ uint32_t*>(dstPtr + i * TileDataD::RowStride),
260	            reinterpret_cast<__ubuf__ uint32_t*>(indexTmpPtr + i * TileDataS::RowStride),
261	            reinterpret_cast<__ubuf__ uint32_t*>(cmpsTmpPtr + i * TileDataTmp::RowStride), 1, 1, 0, 8, 0);
262	        *(cdstPtr + i) = (T)get_rsvd_cnt();
263	    }
264	    set_mask_norm();
265	    set_vector_mask(-1, -1);
266	}
267	
268	template <
269	    typename TileDataD, typename TileDataS, typename TileDataS1, typename TileDataC, typename TileDataTmp,
270	    CmpMode cmpMode>
271	__tf__ AICORE void TGather_cmp(
272	    typename TileDataD::TileDType __out__ dst, typename TileDataS::TileDType __in__ src0,
273	    typename TileDataC::TileDType __in__ cdst, typename TileDataTmp::TileDType __in__ tmp,
274	    typename TileDataS1::TileDType __in__ k_value, uint32_t offset, unsigned srcValidCol, unsigned srcValidRow)
275	{
276	    using T = typename TileDataD::DType;
277	    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
278	    __ubuf__ typename TileDataS::DType* src0Ptr = (__ubuf__ typename TileDataS::DType*)__cce_get_tile_ptr(src0);
279	    __ubuf__ typename TileDataC::DType* cdstPtr = (__ubuf__ typename TileDataC::DType*)__cce_get_tile_ptr(cdst);
280	    __ubuf__ uint8_t* cmpsTmpPtr = (__ubuf__ uint8_t*)__cce_get_tile_ptr(tmp);
281	    uint32_t indexTmpAddr = static_cast<uint32_t>(reinterpret_cast<int64_t>(cmpsTmpPtr)) +
282	                            TileDataTmp::Rows * TileDataTmp::Cols * sizeof(uint8_t);
283	    __ubuf__ T* indexTmpPtr = (__ubuf__ T*)get_imm(indexTmpAddr);
284	    uint32_t cvtTmpAddr = static_cast<uint32_t>(reinterpret_cast<int64_t>(cmpsTmpPtr)) +
285	                          TileDataTmp::Rows * TileDataTmp::Cols * sizeof(uint8_t) +
286	                          TileDataS::Rows * TileDataS::Cols * sizeof(T);
287	
288	    using TIN = typename TileDataS::DType;
289	    using TS = typename TileDataS1::DType;
290	    __ubuf__ TS* kPtr = (__ubuf__ TS*)__cce_get_tile_ptr(k_value);
291	    __ubuf__ TIN* cvtTmpPtr = (__ubuf__ TIN*)get_imm(cvtTmpAddr);
292	
293	    TGather_cmp_InitIndicesKAndTcmps<TileDataD, TileDataS, TileDataS1, TileDataTmp, cmpMode>(
294	        indexTmpPtr, offset, cvtTmpPtr, kPtr, src0Ptr, cmpsTmpPtr, srcValidCol, srcValidRow);
295	
296	    TGather_cmp_ReduceGatherAndCounts<TileDataD, TileDataS, TileDataC, TileDataTmp>(
297	        dstPtr, indexTmpPtr, cmpsTmpPtr, cdstPtr, srcValidRow, srcValidCol);
298	}
299	
300	template <
301	    typename TileDataD, typename TileDataS, typename TileDataS1, typename TileDataC, typename TileDataTmp,
302	    CmpMode cmpMode>
303	PTO_INTERNAL void TGATHER_IMPL(
304	    TileDataD& dst, TileDataS& src0, TileDataS1& k_value, TileDataC& cdst, TileDataTmp& tmp, uint32_t offset)
305	{
306	    static_assert(
307	        std::is_same_v<typename TileDataD::DType, uint32_t> || std::is_same_v<typename TileDataD::DType, int32_t>,
308	        "Fix: TGATHER Dst data type must be int32_t/uint32_t.");
309	    static_assert(
310	        std::is_same_v<typename TileDataS::DType, float> || std::is_same_v<typename TileDataS::DType, half> ||
311	            (std::is_same_v<typename TileDataS::DType, int32_t> && cmpMode == CmpMode::EQ),
312	        "Fix: TGATHER Src data type must be half/float or int32_t while cmpMode is EQ.");
313	    static_assert((cmpMode == CmpMode::GT || cmpMode == CmpMode::EQ), "Fix: TGATHER only support GT or EQ mode");
314	    static_assert(
315	        (TileDataD::Loc == TileType::Vec) && (TileDataS::Loc == TileType::Vec), "Fix: TGATHER expect vec TileType");
316	
317	    unsigned sValidCols = src0.GetValidCol();
318	    unsigned sValidRows = src0.GetValidRow();
319	
320	    TGather_cmp<TileDataD, TileDataS, TileDataS1, TileDataC, TileDataTmp, cmpMode>(
321	        dst.data(), src0.data(), cdst.data(), tmp.data(), k_value.data(), offset, sValidCols, sValidRows);
322	}
323	} // namespace pto
324	#endif
