35	template <GatherOOB Oob>
36	AICORE PTO_INLINE uint32_t mgather_remap(uint32_t idx, uint32_t cap, uint32_t& doRead)
37	{
38	    if constexpr (Oob == GatherOOB::Clamp) {
39	        doRead = 1u;
40	        return (idx >= cap) ? (cap - 1u) : idx;
41	    } else if constexpr (Oob == GatherOOB::Wrap) {
42	        doRead = 1u;
43	        return idx % cap;
44	    } else if constexpr (Oob == GatherOOB::Undefined) {
45	        doRead = 1u;
46	        return idx;
47	    } else {
48	        doRead = (idx < cap) ? 1u : 0u;
49	        return idx;
50	    }
51	}
