59	template <typename T>
60	AICORE PTO_INLINE void MGatherRowDma(__ubuf__ T* dst, __gm__ T* src, uint32_t lenBytes)
61	{
62	    if constexpr (sizeof(T) == 1) {
63	        copy_gm_to_ubuf_align_b8(dst, src, 0, 1, lenBytes, 0, 0, 0, 0);
64	    } else if constexpr (sizeof(T) == 2) {
65	        copy_gm_to_ubuf_align_b16(dst, src, 0, 1, lenBytes, 0, 0, 0, 0);
66	    } else if constexpr (sizeof(T) == 4) {
67	        copy_gm_to_ubuf_align_b32(dst, src, 0, 1, lenBytes, 0, 0, 0, 0);
68	    }
69	}
