73	    __ubuf__ T* dst, __gm__ T* src, uint16_t nBurst, uint32_t lenBytes, uint32_t gmGapBytes, uint32_t ubGapBlocks)
74	{
75	    if constexpr (sizeof(T) == 1) {
76	        copy_gm_to_ubuf_align_b8(dst, src, 0, nBurst, lenBytes, 0, 0, gmGapBytes, ubGapBlocks);
77	    } else if constexpr (sizeof(T) == 2) {
78	        copy_gm_to_ubuf_align_b16(dst, src, 0, nBurst, lenBytes, 0, 0, gmGapBytes, ubGapBlocks);
79	    } else if constexpr (sizeof(T) == 4) {
80	        copy_gm_to_ubuf_align_b32(dst, src, 0, nBurst, lenBytes, 0, 0, gmGapBytes, ubGapBlocks);
81	    }
