84	template <typename T>
85	AICORE PTO_INLINE uint64_t MGatherNZGmOffset(
86	    uint32_t logicalRow, uint32_t logicalCol, int gShape0, int gShape1, int gStride0, int gStride1, int gStride2,
87	    int gStride3, int gStride4)
88	{
89	    constexpr uint32_t kC0 = C0_SIZE_BYTE / sizeof(T);
90	    const uint32_t blockColCombined = logicalCol / kC0;
91	    const uint32_t colInBlock = logicalCol - blockColCombined * kC0;
92	    constexpr uint32_t kFRow = FRACTAL_NZ_ROW;
93	    const uint32_t blockRow = logicalRow / kFRow;
94	    const uint32_t blockColOuter0 = (gShape0 == 1) ? 0u : (blockColCombined / (uint32_t)gShape1);
95	    const uint32_t blockColOuter1 = (gShape0 == 1) ? blockColCombined : (blockColCombined - blockColOuter0 * gShape1);
96	    const uint32_t rowInBlock = logicalRow - blockRow * kFRow;
97	    return (uint64_t)blockColOuter0 * (uint64_t)gStride0 + (uint64_t)blockColOuter1 * (uint64_t)gStride1 +
98	           (uint64_t)blockRow * (uint64_t)gStride2 + (uint64_t)rowInBlock * (uint64_t)gStride3 +
99	           (uint64_t)colInBlock * (uint64_t)gStride4;
100	}
