102	template <GatherOOB Oob, typename T, typename TIdx, typename DstTile, typename IdxTile>
103	__tf__ AICORE void MGatherRowImpl(
104	    typename DstTile::TileDType __out__ dst, __gm__ T* tablePtr, typename IdxTile::TileDType __in__ indices,
105	    uint32_t validRow, uint32_t validCol, uint32_t tableRows, uint32_t tableRowStride)
106	{
107	    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
108	    __ubuf__ TIdx* idxPtr = (__ubuf__ TIdx*)__cce_get_tile_ptr(indices);
109	
110	    PtoSetWaitFlag<PIPE_V, PIPE_S>();
111	    PtoSetWaitFlag<PIPE_MTE3, PIPE_S>();
112	
113	    const uint32_t lenBytes = validCol * sizeof(T);
114	    constexpr uint32_t kRowStride = DstTile::RowStride;
115	
116	    if constexpr (Oob == GatherOOB::Zero) {
117	        for (uint32_t r = 0; r < validRow; r++) {
118	            uint32_t rawIdx = static_cast<uint32_t>(idxPtr[r]);
119	            uint32_t doRead;
120	            uint32_t safeIdx = mgather_remap<Oob>(rawIdx, tableRows, doRead);
121	            __ubuf__ T* dstRow = dstPtr + r * kRowStride;
122	            if (doRead) {
123	                __gm__ T* srcRow = tablePtr + static_cast<uint64_t>(safeIdx) * tableRowStride;
124	                MGatherRowDma<T>(dstRow, srcRow, lenBytes);
125	            } else {
126	                for (uint32_t c = 0; c < validCol; c++) {
127	                    dstRow[c] = static_cast<T>(0);
128	                }
129	            }
130	        }
131	    } else {
132	        for (uint32_t r = 0; r < validRow; r++) {
133	            uint32_t rawIdx = static_cast<uint32_t>(idxPtr[r]);
134	            uint32_t doRead;
135	            uint32_t safeIdx = mgather_remap<Oob>(rawIdx, tableRows, doRead);
136	            if (doRead) {
137	                __gm__ T* srcRow = tablePtr + static_cast<uint64_t>(safeIdx) * tableRowStride;
138	                __ubuf__ T* dstRow = dstPtr + r * kRowStride;
139	                MGatherRowDma<T>(dstRow, srcRow, lenBytes);
140	            }
141	        }
142	    }
143	
144	    PtoSetWaitFlag<PIPE_S, PIPE_MTE2>();
145	    PtoSetWaitFlag<PIPE_MTE2, PIPE_V>();
146	    PtoSetWaitFlag<PIPE_MTE2, PIPE_MTE3>();
147	    PtoSetWaitFlag<PIPE_S, PIPE_V>();
148	    PtoSetWaitFlag<PIPE_S, PIPE_MTE3>();
149	}
