151	template <GatherOOB Oob, typename T, typename TIdx, typename DstTile, typename IdxTile>
152	__tf__ AICORE void MGatherRowNzImpl(
153	    typename DstTile::TileDType __out__ dst, __gm__ T* tablePtr, typename IdxTile::TileDType __in__ indices,
154	    uint32_t validRow, int gShape0, int gShape1, int gShape2, int gStride0, int gStride1, int gStride2, int gStride3)
155	{
156	    constexpr uint32_t kC0 = C0_SIZE_BYTE / sizeof(T);
157	    constexpr uint32_t kFRow = FRACTAL_NZ_ROW;
158	    constexpr uint32_t kFractalRowBytes = kC0 * sizeof(T);
159	
160	    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
161	    __ubuf__ TIdx* idxPtr = (__ubuf__ TIdx*)__cce_get_tile_ptr(indices);
162	
163	    PtoSetWaitFlag<PIPE_V, PIPE_S>();
164	    PtoSetWaitFlag<PIPE_MTE3, PIPE_S>();
165	
166	    const uint32_t tableLogicalRows = (uint32_t)gShape2 * kFRow;
167	    const uint32_t gmGapBytes = ((uint32_t)gStride1 - kC0) * (uint32_t)sizeof(T);
168	    constexpr uint32_t ubGapBlocks = (uint32_t)DstTile::Rows - 1u;
169	    const int64_t tileOuterStrideElem = (int64_t)gShape1 * (int64_t)DstTile::Rows * (int64_t)kC0;
170	
171	    if constexpr (Oob == GatherOOB::Zero) {
172	        constexpr uint32_t kDstNumel = (uint32_t)DstTile::Rows * (uint32_t)DstTile::Cols;
173	        for (uint32_t i = 0; i < kDstNumel; i++) {
174	            dstPtr[i] = static_cast<T>(0);
175	        }
176	    }
177	
178	    for (uint32_t r = 0; r < validRow; r++) {
179	        uint32_t rawIdx = static_cast<uint32_t>(idxPtr[r]);
180	        uint32_t doRead;
181	        uint32_t safeIdx = mgather_remap<Oob>(rawIdx, tableLogicalRows, doRead);
182	        if (doRead) {
183	            const uint32_t srcBlockRow = safeIdx / kFRow;
184	            const uint32_t srcRowInBlock = safeIdx - srcBlockRow * kFRow;
185	            const uint32_t dstBlockRow = r / kFRow;
186	            const uint32_t dstRowInBlock = r - dstBlockRow * kFRow;
187	
188	            for (uint32_t i = 0; i < (uint32_t)gShape0; i++) {
189	                __gm__ T* srcAddr = tablePtr + (int64_t)i * (int64_t)gStride0 +
190	                                    (int64_t)srcBlockRow * (int64_t)gStride2 +
191	                                    (int64_t)srcRowInBlock * (int64_t)gStride3;
192	                __ubuf__ T* dstAddr = dstPtr + (int64_t)i * tileOuterStrideElem +
193	                                      (int64_t)dstBlockRow * (int64_t)kFRow * (int64_t)kC0 +
194	                                      (int64_t)dstRowInBlock * (int64_t)kC0;
195	                MGatherRowMultiDma<T>(dstAddr, srcAddr, (uint16_t)gShape1, kFractalRowBytes, gmGapBytes, ubGapBlocks);
196	            }
197	        }
198	    }
199	
200	    PtoSetWaitFlag<PIPE_S, PIPE_MTE2>();
201	    PtoSetWaitFlag<PIPE_MTE2, PIPE_V>();
202	    PtoSetWaitFlag<PIPE_MTE2, PIPE_MTE3>();
203	    PtoSetWaitFlag<PIPE_S, PIPE_V>();
204	    PtoSetWaitFlag<PIPE_S, PIPE_MTE3>();
205	}
