207	template <GatherOOB Oob, typename T, typename TIdx, typename DstTile, typename IdxTile>
208	__tf__ AICORE void MGatherElemImpl(
209	    typename DstTile::TileDType __out__ dst, __gm__ T* tablePtr, typename IdxTile::TileDType __in__ indices,
210	    uint32_t validRow, uint32_t validCol, uint32_t tableSize)
211	{
212	    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
213	    __ubuf__ TIdx* idxPtr = (__ubuf__ TIdx*)__cce_get_tile_ptr(indices);
214	
215	    PtoSetWaitFlag<PIPE_V, PIPE_S>();
216	    PtoSetWaitFlag<PIPE_MTE3, PIPE_S>();
217	    PtoSetWaitFlag<PIPE_MTE2, PIPE_S>();
218	
219	    constexpr uint32_t kDstRowStride = DstTile::RowStride;
220	    constexpr uint32_t kIdxRowStride = IdxTile::RowStride;
221	
222	    for (uint32_t r = 0; r < validRow; r++) {
223	        const uint32_t idxRowOff = r * kIdxRowStride;
224	        const uint32_t dstRowOff = r * kDstRowStride;
225	        for (uint32_t c = 0; c < validCol; c++) {
226	            const uint32_t idxOff = idxRowOff + c;
227	            const uint32_t dstOff = dstRowOff + c;
228	            uint32_t rawIdx = static_cast<uint32_t>(idxPtr[idxOff]);
229	            uint32_t doRead;
230	            uint32_t safeIdx = mgather_remap<Oob>(rawIdx, tableSize, doRead);
231	            if (doRead) {
232	                dstPtr[dstOff] = tablePtr[safeIdx];
233	            } else if constexpr (Oob == GatherOOB::Zero) {
234	                dstPtr[dstOff] = static_cast<T>(0);
235	            }
236	        }
237	    }
238	
239	    PtoSetWaitFlag<PIPE_S, PIPE_V>();
240	    PtoSetWaitFlag<PIPE_S, PIPE_MTE2>();
241	    PtoSetWaitFlag<PIPE_S, PIPE_MTE3>();
242	}
