244	template <GatherOOB Oob, typename T, typename TIdx, typename DstTile, typename IdxTile>
245	__tf__ AICORE void MGatherElemNzImpl(
246	    typename DstTile::TileDType __out__ dst, __gm__ T* tablePtr, typename IdxTile::TileDType __in__ indices,
247	    uint32_t validRow, uint32_t validCol, uint32_t tableSize, int gShape0, int gShape1, int gStride0, int gStride1,
248	    int gStride2, int gStride3, int gStride4, uint32_t nLogicalCols)
249	{
250	    constexpr uint32_t kC0 = C0_SIZE_BYTE / sizeof(T);
251	    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
252	    __ubuf__ TIdx* idxPtr = (__ubuf__ TIdx*)__cce_get_tile_ptr(indices);
253	
254	    PtoSetWaitFlag<PIPE_V, PIPE_S>();
255	    PtoSetWaitFlag<PIPE_MTE3, PIPE_S>();
256	    PtoSetWaitFlag<PIPE_MTE2, PIPE_S>();
257	
258	    constexpr uint32_t kIdxRowStride = IdxTile::RowStride;
259	    const uint32_t nColBlocks = (validCol + kC0 - 1u) / kC0;
260	    const uint32_t kDstColBlockStride = (uint32_t)DstTile::Rows * kC0;
261	
262	    for (uint32_t bcol = 0; bcol < nColBlocks; bcol++) {
263	        const uint32_t cBase = bcol * kC0;
264	        const uint32_t cLimit = (cBase + kC0 < validCol) ? (cBase + kC0) : validCol;
265	        const uint32_t kInBlock = cLimit - cBase;
266	        __ubuf__ T* dstBlockBase = dstPtr + (uint64_t)bcol * (uint64_t)kDstColBlockStride;
267	        for (uint32_t r = 0; r < validRow; r++) {
268	            const uint32_t idxRowOff = r * kIdxRowStride;
269	            __ubuf__ T* dstRowBase = dstBlockBase + (uint64_t)r * (uint64_t)kC0;
270	            for (uint32_t cInner = 0; cInner < kInBlock; cInner++) {
271	                const uint32_t c = cBase + cInner;
272	                const uint32_t idxOff = idxRowOff + c;
273	                uint32_t rawIdx = static_cast<uint32_t>(idxPtr[idxOff]);
274	                uint32_t doRead;
275	                uint32_t safeIdx = mgather_remap<Oob>(rawIdx, tableSize, doRead);
276	                if (doRead) {
277	                    const uint32_t logicalRow = safeIdx / nLogicalCols;
278	                    const uint32_t logicalCol = safeIdx - logicalRow * nLogicalCols;
279	                    const uint64_t srcOff = MGatherNZGmOffset<T>(
280	                        logicalRow, logicalCol, gShape0, gShape1, gStride0, gStride1, gStride2, gStride3, gStride4);
281	                    dstRowBase[cInner] = tablePtr[srcOff];
282	                } else if constexpr (Oob == GatherOOB::Zero) {
283	                    dstRowBase[cInner] = static_cast<T>(0);
284	                }
285	            }
286	        }
287	    }
288	
289	    PtoSetWaitFlag<PIPE_S, PIPE_V>();
290	    PtoSetWaitFlag<PIPE_S, PIPE_MTE2>();
291	    PtoSetWaitFlag<PIPE_S, PIPE_MTE3>();
292	}
