294	template <GatherOOB Oob, typename T, typename TIdx, typename DstTile>
295	__tf__ AICORE void MGatherGm2L1RowImpl(
296	    typename DstTile::TileDType __out__ dst, __gm__ T* tablePtr, __gm__ TIdx* idxPtr, uint32_t validRow,
297	    uint32_t validCol, uint32_t tableRows, uint32_t tableRowStride)
298	{
299	#if defined(__DAV_CUBE__)
300	    constexpr uint32_t kC0 = C0_SIZE_BYTE / sizeof(T);
301	    __cbuf__ T* dstPtr = (__cbuf__ T*)__cce_get_tile_ptr(dst);
302	    constexpr uint32_t kTileRows = DstTile::Rows;
303	    constexpr uint32_t kTileCols = DstTile::Cols;
304	
305	    if constexpr (Oob == GatherOOB::Zero) {
306	        constexpr uint32_t kColBlocks = kTileCols / kC0;
307	        int64_t repeatConfig = (static_cast<int64_t>(kTileRows) << 16) | static_cast<int64_t>(kColBlocks);
308	        pto_create_cbuf_matrix((__cbuf__ uint16_t*)dstPtr, repeatConfig, 0);
309	    }
310	
311	    for (uint32_t r = 0; r < validRow; r++) {
312	        uint32_t doRead;
313	        uint32_t rawIdx = static_cast<uint32_t>(idxPtr[r]);
314	        uint32_t safeIdx = mgather_remap<Oob>(rawIdx, tableRows, doRead);
315	        if (doRead) {
316	            __gm__ T* srcRow = tablePtr + static_cast<uint64_t>(safeIdx) * tableRowStride;
317	            __cbuf__ T* dstRow = dstPtr + static_cast<uint64_t>(r) * kC0;
318	            pto_copy_gm_to_cbuf_multi_nd2nz<T>(
319	                dstRow, srcRow, 0, 1, 1, static_cast<uint16_t>(validCol), 0, static_cast<uint16_t>(tableRowStride),
320	                static_cast<uint16_t>(kTileRows), 1, 1);
321	        }
322	    }
323	    PtoSetWaitFlag<PIPE_S, PIPE_MTE2>();
324	#endif
325	}
