327	template <GatherOOB Oob, typename T, typename TIdx, typename DstTile>
328	__tf__ AICORE void MGatherGm2L1ElemImpl(
329	    typename DstTile::TileDType __out__ dst, __gm__ T* tablePtr, __gm__ TIdx* idxPtr, __gm__ T* scratchPtr,
330	    uint32_t validRow, uint32_t validCol, uint32_t tableSize, uint32_t idxRowStride)
331	{
332	#if defined(__DAV_CUBE__)
333	    constexpr uint32_t kC0 = C0_SIZE_BYTE / sizeof(T);
334	    constexpr uint32_t kTileCols = DstTile::Cols;
335	    constexpr uint32_t kTileRows = DstTile::Rows;
336	    constexpr uint32_t kTileNumel = kTileRows * kTileCols;
337	    __cbuf__ T* dstPtr = (__cbuf__ T*)__cce_get_tile_ptr(dst);
338	
339	    for (uint32_t i = 0; i < kTileNumel; i++) {
340	        scratchPtr[i] = static_cast<T>(0);
341	    }
342	    for (uint32_t r = 0; r < validRow; r++) {
343	        const uint32_t idxRowOff = r * idxRowStride;
344	        for (uint32_t c = 0; c < validCol; c++) {
345	            uint32_t doRead;
346	            uint32_t rawIdx = static_cast<uint32_t>(idxPtr[idxRowOff + c]);
347	            uint32_t safeIdx = mgather_remap<Oob>(rawIdx, tableSize, doRead);
348	            if (doRead) {
349	                const uint32_t blockCol = c / kC0;
350	                const uint32_t colInBlock = c - blockCol * kC0;
351	                const uint64_t off =
352	                    static_cast<uint64_t>(blockCol) * static_cast<uint64_t>(kTileRows) * static_cast<uint64_t>(kC0) +
353	                    static_cast<uint64_t>(r) * static_cast<uint64_t>(kC0) + static_cast<uint64_t>(colInBlock);
354	                scratchPtr[off] = tablePtr[safeIdx];
355	            }
356	        }
357	    }
358	    const uint32_t totalBytes = kTileNumel * sizeof(T);
359	    constexpr uint32_t kCacheLineBytes = 64;
360	    const uint32_t numLines = (totalBytes + kCacheLineBytes - 1) / kCacheLineBytes;
361	    __gm__ uint8_t* flushPtr = reinterpret_cast<__gm__ uint8_t*>(scratchPtr);
362	    for (uint32_t i = 0; i < numLines; i++) {
363	        dcci(static_cast<__gm__ void*>(flushPtr + i * kCacheLineBytes), cache_line_t::SINGLE_CACHE_LINE);
364	    }
365	    dsb(DSB_DDR);
366	    PtoSetWaitFlag<PIPE_S, PIPE_MTE2>();
367	    const uint16_t lenBurst = static_cast<uint16_t>(kTileNumel * sizeof(T) / BLOCK_BYTE_SIZE);
368	    copy_gm_to_cbuf(dstPtr, scratchPtr, (uint8_t)0, (uint16_t)1, lenBurst, (uint16_t)0, (uint16_t)0, (pad_t)0);
369	#endif
370	}
