372	template <Coalesce Mode, GatherOOB Oob, typename DstTile, typename GlobalTable, typename IdxSrc>
373	PTO_INTERNAL void MGatherCheckGm2L1()
374	{
375	    using T = typename DstTile::DType;
376	
377	    static_assert(
378	        IsValidMGatherDType<T>::value,
379	        "MGATHER A2/A3 GM->L1 data type must be int8/uint8/int16/uint16/int32/uint32/half/bfloat16/float.");
380	    static_assert(
381	        std::is_same_v<typename GlobalTable::DType, __gm__ T>,
382	        "MGATHER A2/A3 GM->L1 table must be a GM GlobalTensor with element type matching the destination.");
383	    static_assert(
384	        std::is_same_v<typename IdxSrc::DType, __gm__ int32_t> ||
385	            std::is_same_v<typename IdxSrc::DType, __gm__ uint32_t>,
386	        "MGATHER A2/A3 GM->L1 indices must be a GM int32_t/uint32_t GlobalTensor.");
387	    static_assert(DstTile::Loc == TileType::Mat, "MGATHER A2/A3 GM->L1 destination must be a Mat tile (L1).");
388	    static_assert(
389	        IsMGatherNZTile<DstTile>::value,
390	        "MGATHER A2/A3 GM->L1 destination must be NZ (BLayout::ColMajor + SLayout::RowMajor + "
391	        "SFractalSize=512).");
392	    static_assert(GlobalTable::layout == Layout::ND, "MGATHER A2/A3 GM->L1 table must use Layout::ND.");
393	    static_assert(
394	        DstTile::Cols % (C0_SIZE_BYTE / sizeof(T)) == 0,
395	        "MGATHER A2/A3 GM->L1 destination tile Cols must be a multiple of C0 (= 32 / sizeof(T)).");
396	    static_assert(
397	        DstTile::Rows % FRACTAL_NZ_ROW == 0,
398	        "MGATHER A2/A3 GM->L1 destination tile Rows must be a multiple of FRACTAL_NZ_ROW (16).");
399	    if constexpr (Mode == Coalesce::Row) {
400	        static_assert(sizeof(T) <= 4, "MGATHER A2/A3 GM->L1 Coalesce::Row supports b8/b16/b32 element types.");
401	    }
402	}
