404	template <Coalesce Mode, GatherOOB Oob, typename DstTile, typename GlobalTable, typename IdxTile>
405	PTO_INTERNAL void MGatherCheck()
406	{
407	    using T = typename DstTile::DType;
408	    using TIdx = typename IdxTile::DType;
409	
410	    static_assert(
411	        IsValidMGatherDType<T>::value,
412	        "MGATHER A2/A3 data type must be int8/uint8/int16/uint16/int32/uint32/half/bfloat16/float.");
413	    static_assert(
414	        std::is_same_v<TIdx, int32_t> || std::is_same_v<TIdx, uint32_t>,
415	        "MGATHER A2/A3 index type must be int32_t or uint32_t.");
416	    static_assert(
417	        std::is_same_v<typename GlobalTable::DType, __gm__ T>,
418	        "MGATHER A2/A3 source table must be a GM GlobalTensor with element type matching the destination.");
419	    static_assert(DstTile::Loc == TileType::Vec, "MGATHER A2/A3 destination must be a Vec tile (UB).");
420	    static_assert(IdxTile::Loc == TileType::Vec, "MGATHER A2/A3 indices must be a Vec tile (UB).");
421	
422	    static_assert(IdxTile::isRowMajor, "MGATHER A2/A3 index tile must be BLayout::RowMajor.");
423	    static_assert(IdxTile::SFractal == SLayout::NoneBox, "MGATHER A2/A3 index tile must be ND (SLayout::NoneBox).");
424	
425	    constexpr bool kIsTableND = (GlobalTable::layout == Layout::ND);
426	    constexpr bool kIsTableNZ = (GlobalTable::layout == Layout::NZ);
427	    constexpr bool kIsDstND = IsMGatherNDTile<DstTile>::value;
428	    constexpr bool kIsDstNZ = IsMGatherNZTile<DstTile>::value;
429	
430	    static_assert(kIsTableND || kIsTableNZ, "MGATHER A2/A3 table must use Layout::ND or Layout::NZ.");
431	    static_assert(
432	        (kIsTableND && kIsDstND) || (kIsTableNZ && kIsDstNZ),
433	        "MGATHER A2/A3 layout pairing must be either:\n"
434	        "  (a) GM Layout::ND + UB tile (BLayout::RowMajor + SLayout::NoneBox), or\n"
435	        "  (b) GM Layout::NZ + UB tile (BLayout::ColMajor + SLayout::RowMajor + SFractalSize=512).");
436	
437	    static_assert(
438	        DstTile::Cols * sizeof(T) % BLOCK_BYTE_SIZE == 0,
439	        "MGATHER A2/A3 destination tile padded Cols*sizeof(T) must be 32-byte aligned.");
440	
441	    if constexpr (kIsTableNZ) {
442	        static_assert(
443	            GlobalTable::staticShape[3] == FRACTAL_NZ_ROW,
444	            "MGATHER A2/A3 NZ table requires staticShape[3] == FRACTAL_NZ_ROW (16).");
445	        static_assert(
446	            GlobalTable::staticShape[4] == C0_SIZE_BYTE / sizeof(T),
447	            "MGATHER A2/A3 NZ table requires staticShape[4] == 32 / sizeof(T).");
448	        static_assert(
449	            DstTile::Cols % (C0_SIZE_BYTE / sizeof(T)) == 0,
450	            "MGATHER A2/A3 NZ destination tile Cols must be a multiple of C0 (= 32 / sizeof(T)).");
451	        static_assert(
452	            DstTile::Rows % FRACTAL_NZ_ROW == 0,
453	            "MGATHER A2/A3 NZ destination tile Rows must be a multiple of FRACTAL_NZ_ROW (16).");
454	    }
455	
456	    constexpr int kDstValidR = DstTile::ValidRow;
457	    constexpr int kDstValidC = DstTile::ValidCol;
458	    constexpr int kIdxValidR = IdxTile::ValidRow;
459	    constexpr int kIdxValidC = IdxTile::ValidCol;
460	
461	    if constexpr (Mode == Coalesce::Row) {
462	        if constexpr (kDstValidR > 0 && kIdxValidR > 0 && kIdxValidC > 0) {
463	            static_assert(
464	                kIdxValidR == 1 && kIdxValidC == kDstValidR,
465	                "MGATHER A2/A3 Coalesce::Row requires index tile valid shape [1, R].");
466	        }
467	    } else {
468	        if constexpr (kDstValidR > 0 && kIdxValidR > 0) {
469	            static_assert(
470	                kIdxValidR == kDstValidR,
471	                "MGATHER A2/A3 Coalesce::Elem requires index tile ValidRow == destination ValidRow.");
472	        }
473	        if constexpr (kDstValidC > 0 && kIdxValidC > 0) {
474	            static_assert(
475	                kIdxValidC == kDstValidC,
476	                "MGATHER A2/A3 Coalesce::Elem requires index tile ValidCol == destination ValidCol.");
477	        }
478	    }
479	}
