481	template <
482	    Coalesce Mode = Coalesce::Row, GatherOOB Oob = GatherOOB::Undefined, typename DstTile, typename GlobalTable,
483	    typename IdxTile>
484	PTO_INTERNAL void MGATHER_IMPL(DstTile& dst, GlobalTable& table, IdxTile& indices)
485	{
486	    using T = typename DstTile::DType;
487	
488	    if constexpr (DstTile::Loc == TileType::Mat) {
489	        MGatherCheckGm2L1<Coalesce::Row, Oob, DstTile, GlobalTable, IdxTile>();
490	        using TIdx = std::conditional_t<std::is_same_v<typename IdxTile::DType, __gm__ uint32_t>, uint32_t, int32_t>;
491	        __gm__ T* tablePtr = reinterpret_cast<__gm__ T*>(table.data());
492	        __gm__ TIdx* idxPtr = reinterpret_cast<__gm__ TIdx*>(indices.data());
493	        const uint32_t validRow = dst.GetValidRow();
494	        const uint32_t validCol = dst.GetValidCol();
495	        const uint32_t tableRows = static_cast<uint32_t>(
496	            table.GetShape(GlobalTensorDim::DIM_0) * table.GetShape(GlobalTensorDim::DIM_1) *
497	            table.GetShape(GlobalTensorDim::DIM_2) * table.GetShape(GlobalTensorDim::DIM_3));
498	        const uint32_t tableRowStride = static_cast<uint32_t>(table.GetStride(GlobalTensorDim::DIM_3));
499	        MGatherGm2L1RowImpl<Oob, T, TIdx, DstTile>(
500	            dst.data(), tablePtr, idxPtr, validRow, validCol, tableRows, tableRowStride);
501	        return;
502	    } else {
503	        using TIdx = typename IdxTile::DType;
504	
505	        MGatherCheck<Mode, Oob, DstTile, GlobalTable, IdxTile>();
506	
507	        __gm__ T* tablePtr = reinterpret_cast<__gm__ T*>(table.data());
508	
509	        const uint32_t validRow = dst.GetValidRow();
510	        const uint32_t validCol = dst.GetValidCol();
511	
512	        constexpr bool kIsTableNZ = (GlobalTable::layout == Layout::NZ);
513	
514	        if constexpr (kIsTableNZ) {
515	            const int gShape0 = static_cast<int>(table.GetShape(GlobalTensorDim::DIM_0));
516	            const int gShape1 = static_cast<int>(table.GetShape(GlobalTensorDim::DIM_1));
517	            const int gShape2 = static_cast<int>(table.GetShape(GlobalTensorDim::DIM_2));
518	            const int gStride0 = static_cast<int>(table.GetStride(GlobalTensorDim::DIM_0));
519	            const int gStride1 = static_cast<int>(table.GetStride(GlobalTensorDim::DIM_1));
520	            const int gStride2 = static_cast<int>(table.GetStride(GlobalTensorDim::DIM_2));
521	            const int gStride3 = static_cast<int>(table.GetStride(GlobalTensorDim::DIM_3));
522	            const int gStride4 = static_cast<int>(table.GetStride(GlobalTensorDim::DIM_4));
523	
524	            if constexpr (Mode == Coalesce::Row) {
525	                MGatherRowNzImpl<Oob, T, TIdx, DstTile, IdxTile>(
526	                    dst.data(), tablePtr, indices.data(), validRow, gShape0, gShape1, gShape2, gStride0, gStride1,
527	                    gStride2, gStride3);
528	            } else {
529	                constexpr uint32_t kC0 = C0_SIZE_BYTE / sizeof(T);
530	                const uint32_t nLogicalCols = static_cast<uint32_t>(gShape0 * gShape1) * kC0;
531	                const uint32_t tableSize = static_cast<uint32_t>(gShape2 * FRACTAL_NZ_ROW) * nLogicalCols;
532	                MGatherElemNzImpl<Oob, T, TIdx, DstTile, IdxTile>(
533	                    dst.data(), tablePtr, indices.data(), validRow, validCol, tableSize, gShape0, gShape1, gStride0,
534	                    gStride1, gStride2, gStride3, gStride4, nLogicalCols);
535	            }
536	        } else {
537	            if constexpr (Mode == Coalesce::Row) {
538	                const uint32_t tableRows = static_cast<uint32_t>(
539	                    table.GetShape(GlobalTensorDim::DIM_0) * table.GetShape(GlobalTensorDim::DIM_1) *
540	                    table.GetShape(GlobalTensorDim::DIM_2) * table.GetShape(GlobalTensorDim::DIM_3));
541	                const uint32_t tableRowStride = static_cast<uint32_t>(table.GetStride(GlobalTensorDim::DIM_3));
542	                MGatherRowImpl<Oob, T, TIdx, DstTile, IdxTile>(
543	                    dst.data(), tablePtr, indices.data(), validRow, validCol, tableRows, tableRowStride);
544	            } else {
545	                const uint32_t tableSize = static_cast<uint32_t>(
546	                    table.GetShape(GlobalTensorDim::DIM_0) * table.GetShape(GlobalTensorDim::DIM_1) *
547	                    table.GetShape(GlobalTensorDim::DIM_2) * table.GetShape(GlobalTensorDim::DIM_3) *
548	                    table.GetShape(GlobalTensorDim::DIM_4));
549	                MGatherElemImpl<Oob, T, TIdx, DstTile, IdxTile>(
550	                    dst.data(), tablePtr, indices.data(), validRow, validCol, tableSize);
551	            }
552	        }
553	    }
554	}
