556	template <
557	    Coalesce Mode = Coalesce::Elem, GatherOOB Oob = GatherOOB::Undefined, typename DstTile, typename GlobalTable,
558	    typename IdxSrc, typename GlobalScratch>
559	PTO_INTERNAL void MGATHER_IMPL(DstTile& dst, GlobalTable& table, IdxSrc& indices, GlobalScratch& scratch)
560	{
561	    using T = typename DstTile::DType;
562	
563	    MGatherCheckGm2L1<Coalesce::Elem, Oob, DstTile, GlobalTable, IdxSrc>();
564	    static_assert(
565	        std::is_same_v<typename GlobalScratch::DType, __gm__ T>,
566	        "MGATHER A2/A3 GM->L1 scratch must be a GM GlobalTensor with element type matching the destination.");
567	
568	    using TIdx = std::conditional_t<std::is_same_v<typename IdxSrc::DType, __gm__ uint32_t>, uint32_t, int32_t>;
569	    __gm__ T* tablePtr = reinterpret_cast<__gm__ T*>(table.data());
570	    __gm__ TIdx* idxPtr = reinterpret_cast<__gm__ TIdx*>(indices.data());
571	    __gm__ T* scratchPtr = reinterpret_cast<__gm__ T*>(scratch.data());
572	
573	    const uint32_t validRow = dst.GetValidRow();
574	    const uint32_t validCol = dst.GetValidCol();
575	    const uint32_t tableSize = static_cast<uint32_t>(
576	        table.GetShape(GlobalTensorDim::DIM_0) * table.GetShape(GlobalTensorDim::DIM_1) *
577	        table.GetShape(GlobalTensorDim::DIM_2) * table.GetShape(GlobalTensorDim::DIM_3) *
578	        table.GetShape(GlobalTensorDim::DIM_4));
579	    const uint32_t idxRowStride = static_cast<uint32_t>(indices.GetStride(GlobalTensorDim::DIM_3));
580	
581	    MGatherGm2L1ElemImpl<Oob, T, TIdx, DstTile>(
582	        dst.data(), tablePtr, idxPtr, scratchPtr, validRow, validCol, tableSize, idxRowStride);
583	}
584	
585	} // namespace pto
586	
587	#endif // MGATHER_HPP
