22	template <typename TileDataDst, typename TileDataSrc, typename TileInd>
23	PTO_INTERNAL void TSCATTER_IMPL(TileDataDst& dst, TileDataSrc& src, TileInd& indexes)
24	{
25	    using IndexT = typename TileInd::DType;
26	    static_assert(std::is_integral_v<IndexT>, "TSCATTER: indexes must be an integral type");
27	
28	    const unsigned validRow = indexes.GetValidRow();
29	    const unsigned validCol = indexes.GetValidCol();
30	    if (validRow == 0 || validCol == 0) {
31	        return;
32	    }
33	
34	    for (unsigned i = 0; i < validRow; ++i) {
35	        for (unsigned j = 0; j < validCol; ++j) {
36	            const size_t srcOff = GetTileElementOffset<TileDataSrc>(i, j);
37	            const size_t idxOff = GetTileElementOffset<TileInd>(i, j);
38	            const auto dstRow = static_cast<unsigned>(indexes.data()[idxOff]);
39	            dst.data()[dstRow] = src.data()[srcOff];
