44	template <MaskPattern maskPattern, typename DstTileData, typename SrcTileData>
45	PTO_INTERNAL void TScatter(
46	    typename DstTileData::TileDType dst, typename SrcTileData::TileDType src, unsigned validRow, unsigned validCol)
47	{
48	    unsigned sR = 0;
49	    unsigned sC = 0;
50	    for (unsigned r = 0; r < validRow; r++) {
51	        for (unsigned c = 0; c < validCol; c++) {
52	            const size_t didx = GetTileElementOffset<DstTileData>(r, c);
53	            if (MaskSelect(maskPattern, c)) {
54	                const size_t sidx = GetTileElementOffset<SrcTileData>(sR, sC);
55	                dst[didx] = static_cast<typename DstTileData::DType>(src[sidx]);
56	                if (++sC == SrcTileData::Cols) {
57	                    sC = 0;
