16	namespace pto {
17	template <typename DstTile, typename T>
18	PTO_INTERNAL void InitUBBuffer(__ubuf__ T* dstPtr)
19	{
20	    using U = std::conditional_t<sizeof(T) == 4, uint32_t, uint16_t>;
21	    __ubuf__ U* dst = (__ubuf__ U*)dstPtr;
22	
23	    // tile must be 32B align, the result is no remainder
24	    constexpr uint32_t numel = DstTile::Numel * sizeof(T) / sizeof(U);
25	    set_mask_count();
26	    set_vector_mask(0, numel);
27	    vector_dup(dst, (U)0, 0, 1, 1, 8, 8);
28	    set_mask_norm();
29	    set_vector_mask(-1, -1);
30	#ifndef __PTO_AUTO__
31	    PtoSetWaitFlag<PIPE_V, PIPE_S>();
32	#endif
33	}
34	
35	template <typename DstTile, typename SrcTile, typename IdxTile>
36	__tf__ PTO_INTERNAL void TScatterImpl(
37	    typename DstTile::TileDType __out__ dst, typename SrcTile::TileDType __in__ src,
38	    typename IdxTile::TileDType __in__ idx, unsigned validRow, unsigned validCol)
39	{
40	    using T = typename DstTile::DType;
41	    using TI = typename IdxTile::DType;
42	    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
43	    __ubuf__ T* srcPtr = (__ubuf__ T*)__cce_get_tile_ptr(src);
44	    __ubuf__ TI* indPtr = (__ubuf__ TI*)__cce_get_tile_ptr(idx);
45	
46	    // Initialize dst UB buffer
47	    InitUBBuffer<DstTile>(dstPtr);
48	
49	    for (int i = 0; i < validRow; i++) {
50	        for (int j = 0; j < validCol; j++) {
51	            TI ix = *(indPtr + i * IdxTile::Cols + j);
52	            dstPtr[ix] = srcPtr[i * SrcTile::Cols + j];
53	        }
54	    }
55	#ifndef __PTO_AUTO__
56	    PtoSetWaitFlag<PIPE_S, PIPE_V>();
57	#endif
58	}
59	
60	template <typename DstTile, typename SrcTile, typename IdxTile>
61	PTO_INTERNAL void TSCATTER_IMPL(DstTile& dst, SrcTile& src, IdxTile& idx)
62	{
63	    using TD = typename DstTile::DType;
64	    using TS = typename SrcTile::DType;
65	    using TI = typename IdxTile::DType;
66	    static_assert(
67	        std::is_same<TD, int32_t>::value || std::is_same<TD, int16_t>::value || std::is_same<TD, int8_t>::value ||
68	            std::is_same<TD, uint32_t>::value || std::is_same<TD, uint16_t>::value ||
69	            std::is_same<TD, uint8_t>::value || std::is_same<TD, half>::value || std::is_same<TD, float16_t>::value ||
70	            std::is_same<TD, float32_t>::value || std::is_same<TD, bfloat16_t>::value,
71	        "TSCATTER: Invalid data type.");
72	    static_assert(std::is_same<TD, TS>::value, "TSCATTER: Data type of dst and src must be the same.");
73	    static_assert(
74	        (sizeof(TD) == 4 && sizeof(TI) == 4) || (sizeof(TD) == 2 && sizeof(TI) == 2) ||
75	            (sizeof(TD) == 1 && sizeof(TI) == 2),
76	        "TSCATTER: Invalid data type of idx.");
77	    static_assert(
78	        std::is_same<TI, uint16_t>::value || std::is_same<TI, uint32_t>::value || std::is_same<TI, int16_t>::value ||
79	            std::is_same<TI, int32_t>::value,
80	        "TSCATTER: Invalid data type of idx.");
81	    static_assert(
82	        DstTile::Loc == TileType::Vec && SrcTile::Loc == TileType::Vec && IdxTile::Loc == TileType::Vec,
83	        "TSCATTER: TileType of src and dst tiles must be TileType::Vec.");
84	    static_assert(
85	        DstTile::ValidCol <= DstTile::Cols && SrcTile::ValidCol <= SrcTile::Cols && IdxTile::ValidCol <= IdxTile::Cols,
86	        "TSCATTER: Number of valid columns must not be greater than number of tile columns.");
87	    static_assert(
88	        DstTile::ValidRow <= DstTile::Rows && SrcTile::ValidRow <= SrcTile::Rows && IdxTile::ValidRow <= IdxTile::Rows,
89	        "TSCATTER: Number of valid rows must not be greater than number of tile rows.");
90	
91	    unsigned validRow = idx.GetValidRow();
92	    unsigned validCol = idx.GetValidCol();
93	
94	    TScatterImpl<DstTile, SrcTile, IdxTile>(dst.data(), src.data(), idx.data(), validRow, validCol);
95	}
96	
97	template <MaskPattern mask, int RowStride>
98	PTO_INTERNAL int GetIdxByMask(int i, int j)
99	{
100	    switch (mask) {
101	        case MaskPattern::P0101:
102	            return i * RowStride + PTO_TIME_2 * j + PTO_IDX_0;
103	        case MaskPattern::P1010:
104	            return i * RowStride + PTO_TIME_2 * j + PTO_IDX_1;
105	        case MaskPattern::P0001:
106	            return i * RowStride + PTO_TIME_4 * j + PTO_IDX_0;
107	        case MaskPattern::P0010:
108	            return i * RowStride + PTO_TIME_4 * j + PTO_IDX_1;
109	        case MaskPattern::P0100:
110	            return i * RowStride + PTO_TIME_4 * j + PTO_IDX_2;
111	        case MaskPattern::P1000:
112	            return i * RowStride + PTO_TIME_4 * j + PTO_IDX_3;
113	        default:
114	            return i * RowStride + j;
115	    }
116	}
117	
118	template <MaskPattern mask, auto ScatterType = ScatterAxis::SCATTER_ROW, typename DstTile, typename SrcTile>
119	__tf__ PTO_INTERNAL void TScatterMaskImpl(
120	    typename DstTile::TileDType __out__ dst, typename SrcTile::TileDType __in__ src, unsigned validRow,
121	    unsigned validCol)
122	{
123	    using T = typename DstTile::DType;
124	    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
125	    __ubuf__ T* srcPtr = (__ubuf__ T*)__cce_get_tile_ptr(src);
126	    constexpr unsigned dstStride = DstTile::RowStride;
127	    constexpr unsigned srcStride = SrcTile::RowStride;
128	
129	    // Initialize dst UB buffer
130	    InitUBBuffer<DstTile>(dstPtr);
131	
132	    if constexpr (ScatterType == ScatterAxis::SCATTER_COL) {
133	        using copyType = std::conditional_t<sizeof(T) == sizeof(int32_t), __ubuf__ int32_t, __ubuf__ int16_t>;
134	        uint16_t stride = 0;
135	        set_mask_count();
136	        set_vector_mask(0, validCol);
137	        for (int i = 0; i < validRow; i++) {
138	            stride = GetStrideByMask<mask, dstStride>(i);
139	            vcopy((copyType*)(dstPtr + stride), (copyType*)(srcPtr + i * srcStride), 1, 1, 1, 8, 8);
140	        }
141	        set_mask_norm();
142	        set_vector_mask(-1, -1);
143	    } else {
144	        int idx = 0;
145	        for (int i = 0; i < validRow; i++) {
146	            for (int j = 0; j < validCol; j++) {
147	                idx = GetIdxByMask<mask, DstTile::RowStride>(i, j);
148	                dstPtr[idx] = srcPtr[i * SrcTile::Cols + j];
149	            }
150	        }
151	    }
152	#ifndef __PTO_AUTO__
153	    PtoSetWaitFlag<PIPE_S, PIPE_V>();
154	#endif
155	}
156	
157	template <MaskPattern mask, auto ScatterType = ScatterAxis::SCATTER_ROW, typename DstTile, typename SrcTile>
158	PTO_INTERNAL void TSCATTER_IMPL(DstTile& dst, SrcTile& src)
159	{
160	    unsigned validRow = src.GetValidRow();
161	    unsigned validCol = src.GetValidCol();
162	    if constexpr (mask == MaskPattern::P1111) {
163	        PTO_ASSERT(validRow == dst.GetValidRow(), "TSCATTER: validRow of src must match dst.");
164	        PTO_ASSERT(validCol == dst.GetValidCol(), "TSCATTER: validCol of src must match dst.");
165	        return TMOV_IMPL(dst, src);
166	    } else {
167	        using T = typename DstTile::DType;
168	        static_assert(
169	            std::is_same<T, int32_t>::value || std::is_same<T, int16_t>::value || std::is_same<T, int8_t>::value ||
170	                std::is_same<T, uint32_t>::value || std::is_same<T, uint16_t>::value ||
171	                std::is_same<T, uint8_t>::value || std::is_same<T, half>::value || std::is_same<T, float16_t>::value ||
172	                std::is_same<T, float32_t>::value || std::is_same<T, bfloat16_t>::value,
173	            "TSCATTER: Invalid data type.");
174	        static_assert(
175	            std::is_same_v<T, typename SrcTile::DType>, "TSCATTER: Data type of dst and src must be the same.");
176	
177	        static_assert(
178	            DstTile::Loc == TileType::Vec && SrcTile::Loc == TileType::Vec,
179	            "TSCATTER: TileType of src and dst tiles must be TileType::Vec.");
180	        static_assert(
181	            DstTile::ValidCol <= DstTile::Cols && SrcTile::ValidCol <= SrcTile::Cols,
182	            "TSCATTER: Number of valid columns must not be greater than number of tile columns.");
183	        static_assert(
184	            DstTile::ValidRow <= DstTile::Rows && SrcTile::ValidRow <= SrcTile::Rows,
185	            "TSCATTER: Number of valid rows must not be greater than number of tile rows.");
186	        static_assert(
187	            mask >= MaskPattern::P0101 && mask <= MaskPattern::P1111,
188	            "TSCATTER: MaskPattern parameter value out of range: must be P0101...P1111 inclusive.");
189	
190	        if constexpr (ScatterType == ScatterAxis::SCATTER_COL) {
191	            PTO_ASSERT(
192	                dst.GetValidRow() == validRow * GetTimesByMask<mask>,
193	                "TSCATTER: validRow of dst must be 2 or 4 times that of src.");
194	            PTO_ASSERT(dst.GetValidCol() == validCol, "TSCATTER: validCol of src must match dst.");
195	        } else {
196	            PTO_ASSERT(validRow == dst.GetValidRow(), "TSCATTER: validRow of src must match dst.");
197	            PTO_ASSERT(
198	                dst.GetValidCol() == validCol * GetTimesByMask<mask>,
199	                "TSCATTER: validCol of dst must be 2 or 4 times that of src.");
200	        }
201	        TScatterMaskImpl<mask, ScatterType, DstTile, SrcTile>(dst.data(), src.data(), validRow, validCol);
202	    }
203	}
204	} // namespace pto
205	
206	#endif
