19	AICORE void runTScatter(__gm__ float __out__* out, __gm__ float __in__* src, __gm__ uint16_t __in__* idx)
20	{
21	    using TileT = Tile<TileType::Vec, float, kTRows_, kTCols_, BLayout::RowMajor, -1, -1>;
22	    using IdxT = Tile<TileType::Vec, uint16_t, idxRows_, idxCols_, BLayout::RowMajor, -1, -1>;
23	
24	    using SrcShape = Shape<1, 1, 1, kTRows_, kTCols_>;
25	    using SrcStride = Stride<1, 1, 1, kTCols_, 1>;
26	    using GTf = GlobalTensor<float, SrcShape, SrcStride>;
27	
28	    using SrcShapeIdx = Shape<1, 1, 1, idxRows_, idxCols_>;
29	    using SrcStrideIdx = Stride<1, 1, 1, idxCols_, 1>;
30	    using GTi = GlobalTensor<uint16_t, SrcShapeIdx, SrcStrideIdx>;
31	
32	    TileT srcTile(kTRows_, kTCols_);
33	    TileT dstTile(kTRows_, kTCols_);
34	    IdxT idxTile(idxRows_, idxCols_);
35	
36	    GTf srcGlobal(src);
37	    GTf dstGlobal(out);
38	    GTi idxGlobal(idx);
39	
40	    TASSIGN(srcTile, 0);
41	    TASSIGN(dstTile, kTRows_ * kTCols_ * sizeof(typename TileT::DType));
42	    TASSIGN(idxTile, 2 * kTRows_ * kTCols_ * sizeof(typename TileT::DType));
43	
44	    TLOAD(srcTile, srcGlobal);
45	    TLOAD(idxTile, idxGlobal);
46	    TEXPANDS(dstTile, 0.0f);
47	    TSCATTER(dstTile, srcTile, idxTile);
48	    TSTORE(dstGlobal, dstTile);
49	    out = dstGlobal.data();
50	}
