63	    auto ScatterDirection>
64	AICORE void runTScatterMaskedGeneric(__gm__ T __out__* out, __gm__ T __in__* src)
65	{
66	    using DynShapeSrc = Shape<1, 1, 1, kSrcRows_, kSrcCols_>;
67	    using DynStridSrc = Stride<1, 1, 1, kSrcCols_, 1>;
68	    using GlobalSrc = GlobalTensor<T, DynShapeSrc, DynStridSrc>;
69	
70	    using DynShapeDst = Shape<1, 1, 1, kDstRows_, kDstCols_>;
71	    using DynStridDst = Stride<1, 1, 1, kDstCols_, 1>;
72	    using GlobalDst = GlobalTensor<T, DynShapeDst, DynStridDst>;
73	    using SrcTileData = Tile<TileType::Vec, T, kSrcRows_, kSrcCols_, BLayout::RowMajor, -1, -1>;
74	    using DstTileData = Tile<TileType::Vec, T, kDstRows_, kDstCols_, BLayout::RowMajor, -1, -1>;
75	
76	    SrcTileData srcTile(kSrcRows_, kSrcCols_);
77	    DstTileData dstTile(kDstRows_, kDstCols_);
78	    TASSIGN(srcTile, 0x0);
