19	template <typename T, int kGRows_, int kGCols_, int kTRows_, int kTCols_, MaskPattern maskPattern>
20	AICORE void runTGATHER(__gm__ T __out__* out, __gm__ T __in__* src)
21	{
22	    using DynShapeDim5 = Shape<1, 1, 1, kGRows_, kGCols_>;
23	    using DynStridDim5 = Stride<1, 1, 1, kGCols_, 1>;
24	    using GlobalData = GlobalTensor<T, DynShapeDim5, DynStridDim5>;
25	    using TileData = Tile<TileType::Vec, T, (kTRows_ + 5), (kTCols_ + 32), BLayout::RowMajor, -1, -1>;
26	    using DstTileData = Tile<TileType::Vec, T, kTRows_, kTCols_, BLayout::RowMajor, -1, -1>;
27	    TileData srcTile(kTRows_, kTCols_);
28	    DstTileData dstTile(kTRows_, kTCols_);
29	    TASSIGN(srcTile, 0x0);
30	    TASSIGN(dstTile, 0x0 + (kTRows_ + 5) * (kTCols_ + 32) * sizeof(T));
31	
32	    GlobalData srcGlobal(src);
33	    GlobalData dstGlobal(out);
34	
35	    TLOAD(srcTile, srcGlobal);
36	    set_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
37	    wait_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
38	    TGATHER<DstTileData, TileData, maskPattern>(dstTile, srcTile);
39	    set_flag(PIPE_V, PIPE_MTE3, EVENT_ID1);
40	    wait_flag(PIPE_V, PIPE_MTE3, EVENT_ID1);
41	    TSTORE(dstGlobal, dstTile);
42	    out = dstGlobal.data();
43	}
